import {Vector3,Matrix3,LightingNode,TextureNode} from 'three/webgpu';
import {Fn,If,Loop,Break,uniform,nodeObject,texture,textureCubeUV,positionWorld,normalWorld,normalView,clearcoatNormalView,bentNormalView,positionViewDirection,roughness,clearcoatRoughness,cameraViewMatrix,mix,vec2,vec3,vec4,ivec2,int,float,cache} from 'three/tsl';
import {gpuProbeVolumeNodes} from './reflection-probe-volume-gpu.js';
import {probeMapLayout} from './reflection-probe-blend.js';

// Copy coordinates stay in the backend's native texture origin. Flip within
// each copied source rectangle, rather than flipping the whole packed atlas.
class AtlasTextureNode extends TextureNode{
 setupUV(builder,uv){const source=this.getBase(),rect=source.atlasRect,local=builder.isFlipY()?source.atlasFlip.greaterThan(.5).select(vec2(uv.x,float(1).sub(uv.y)),uv):uv;return rect.xy.add(local.mul(rect.zw));}
}
class BaseTextureNode extends TextureNode{getUniformHash(){return this.getBase().uuid;}}
export function createGPUProbeAtlasEnvironment(atlas){
 const table=texture(atlas.table),width=uniform(atlas.width,'int'),count=uniform(atlas.count,'int'),base=nodeObject(new BaseTextureNode(atlas.target.texture)),baseLayout=uniform(new Vector3()),baseIntensity=uniform(0),baseEnabled=uniform(0),baseRotation=uniform(new Matrix3());let atlasMap=atlas.target.texture;
 const load=(index,field)=>{const at=int(index).mul(9).add(field);return table.load(ivec2(at.mod(width),at.div(width)));};
 const choose=point=>cache(Fn(()=>{const first=int(-1).toVar(),second=int(-1).toVar(),weights=vec2(0).toVar(),at=point.toVar();Loop({start:int(0),end:count,type:'int',condition:'<'},({i})=>{const lo=load(i,1).toVar(),hi=load(i,2).toVar(),box=gpuProbeVolumeNodes({minimum:lo.xyz,maximum:hi.xyz,localX:load(i,3),localY:load(i,4),localZ:load(i,5),faceScale:load(i,6).xyz,blend:lo.w},at,vec3(0,0,1),vec3(0));If(box.fade.greaterThan(0),()=>{If(first.lessThan(0),()=>{first.assign(i);weights.x.assign(box.fade);}).Else(()=>{second.assign(i);weights.y.assign(box.fade);Break();});});});return vec4(float(first),float(second),weights);})()),selection=choose(positionWorld);
 const sampled=[];
 const light=(ray,at,level,diffuse=false,choice=selection)=>Fn(()=>{const direction=ray.toVar(),position=at.toVar(),lod=level.toVar(),selected=choice.toVar(),total=selected.z.add(selected.w).toVar(),result=vec3(0).toVar();If(baseEnabled.greaterThan(0).and(total.lessThan(1)),()=>{const rotated=baseRotation.mul(vec3(direction.x,direction.y.negate(),direction.z)).mul(vec3(1,-1,1));result.addAssign(textureCubeUV(base,vec3(rotated.x,rotated.y.negate(),rotated.z),lod,baseLayout.x,baseLayout.y,baseLayout.z).mul(baseIntensity).mul(float(1).sub(total)));});for(let slot=0;slot<2;slot++){const index=int(slot===0?selected.x:selected.y),weight=slot===0?selected.z:selected.w;If(index.greaterThanEqual(0),()=>{const center=load(index,0).toVar(),lo=load(index,1).toVar(),hi=load(index,2).toVar(),scale=load(index,6).toVar(),layout=load(index,7).toVar(),rect=load(index,8).toVar(),box=gpuProbeVolumeNodes({minimum:lo.xyz,maximum:hi.xyz,localX:load(index,3),localY:load(index,4),localZ:load(index,5),faceScale:scale.xyz,blend:lo.w},position,direction,center.xyz),projected=diffuse?direction:scale.w.greaterThan(.5).select(box.projected,direction),sampler=nodeObject(new AtlasTextureNode(atlasMap));sampler.atlasRect=rect;sampler.atlasFlip=layout.w;sampled.push(sampler);result.addAssign(textureCubeUV(sampler,vec3(projected.x,projected.y.negate(),projected.z),lod,layout.x,layout.y,layout.z).mul(center.w).mul(diffuse?hi.w:float(1)).mul(weight.div(total.max(1))));});}return result;})();
 class ProbeEnvironment extends LightingNode{setup(builder){const radiance=(normal,level)=>light(mix(positionViewDirection.negate().reflect(normal),normal,level.mul(level)).normalize().transformDirection(cameraViewMatrix),positionWorld,level),normal=builder.material.useAnisotropy===true||builder.material.anisotropy>0?bentNormalView:normalView;builder.context.radiance.addAssign(cache(radiance(normal,roughness)));builder.context.iblIrradiance.addAssign(cache(light(normalWorld,positionWorld,float(1),true).mul(Math.PI)));if(builder.context.lightingModel.clearcoatRadiance)builder.context.lightingModel.clearcoatRadiance.addAssign(cache(radiance(clearcoatNormalView,clearcoatRoughness)));}}
 return {node:new ProbeEnvironment(),refraction(ray,at,level){return cache(light(ray,at,level,false,choose(at)));},update(_p,_texture,_p2,_texture2,fallback,intensity=1,rotation=null){base.value=fallback||atlasMap;baseLayout.value.fromArray(probeMapLayout(base.value));baseEnabled.value=fallback?1:0;baseIntensity.value=intensity;if(rotation)baseRotation.value.copy(rotation);else baseRotation.value.identity();},setAtlas(value){table.value=value.table;width.value=value.width;count.value=value.count;atlasMap=value.target.texture;for(const sampler of sampled)sampler.value=atlasMap;},dispose(){for(const sampler of sampled)sampler.value=null;table.value=base.value=null;}};
}
